exports.userTypeDefs = "\n    type User {\n        _id: ID!\n        name: String!\n        email: String!\n        phone: String!\n        role: String!\n        designation: Designation\n        dateOfBirth: String\n        address: String\n        membershipId: String\n        membershipStatus: String!\n        membershipFee: Float\n        membershipPaidDate: String\n        referralCode: String!\n        referredBy: User\n        totalReferrals: Int!\n        totalDonationsReferred: Float!\n        idCardUrl: String\n        certificateUrl: String\n        appointmentLetterUrl: String\n        isEmailVerified: Boolean!\n        lastLogin: String\n        created_at: String!\n        updated_at: String!\n    }\n\n    type MembershipPaymentOrder {\n        orderId: String!\n        amount: Float!\n        currency: String!\n        membershipFee: Float!\n    }\n\n    type AuthPayload {\n        token: String!\n        user: User!\n    }\n\n    input RegisterInput {\n        name: String!\n        email: String!\n        password: String!\n        phone: String!\n        designation: ID\n        dateOfBirth: String\n        address: String\n        referralCode: String\n    }\n\n    input LoginInput {\n        email: String!\n        password: String!\n    }\n\n    extend type Query {\n        getUsers(limit: Int, offset: Int): [User!]!\n        getUser(id: ID!): User\n        getUserByReferralCode(referralCode: String!): User\n        me: User\n    }\n\n    extend type Mutation {\n        register(input: RegisterInput!): AuthPayload!\n        login(input: LoginInput!): AuthPayload!\n        updateMembershipStatus(userId: ID!, status: String!): User!\n        generateMembershipId(userId: ID!): User!\n        payMembershipFee(designationId: ID): MembershipPaymentOrder!\n        verifyMembershipPayment(orderId: String!, paymentId: String!, signature: String!): User!\n    }\n";
